import json

# Simplified STIX bundle (in reality, fetched via TAXII server)
stix_bundle = {
    "type": "bundle",
    "objects": [
        {
            "type": "indicator",
            "pattern": "[ipv4-addr:value = '203.0.113.50']",
            "labels": ["malicious-activity"],
            "valid_from": "2026-01-15T00:00:00Z"
        },
        {
            "type": "indicator",
            "pattern": "[domain-name:value = 'evil-c2.example.com']",
            "labels": ["malicious-activity"]
        },
        {
            "type": "attack-pattern",
            "name": "Spear Phishing Attachment",
            "external_references": [
                {"source_name": "mitre-attack", "external_id": "T1566.001"}
            ]
        }
    ]
}

# Extract IOCs and ATT&CK mappings
iocs = []
attack_refs = []

for obj in stix_bundle["objects"]:
    if obj["type"] == "indicator":
        iocs.append({"pattern": obj["pattern"], "labels": obj["labels"]})
    elif obj["type"] == "attack-pattern":
        for ref in obj.get("external_references", []):
            if ref["source_name"] == "mitre-attack":
                attack_refs.append({"name": obj["name"], "technique": ref["external_id"]})

print(f'Extracted {len(iocs)} IOCs and {len(attack_refs)} ATT&CK mappings')
for ioc in iocs:
    print(f'  IOC: {ioc["pattern"]}')
for ref in attack_refs:
    print(f'  ATT&CK: {ref["technique"]} - {ref["name"]}')
